#[test]
fn range_iter_rejects_two_var_handles_and_option_wrappers_e2009() { for src in ["fn f(doc serde_json.value) error {\n    for i, u in doc.array(\"users\")? {\n        _ = i\n        _ = u\n    }\n    return nil\n}\n", "fn f(doc serde_json.value) {\n    for i, u in doc {\n        _ = i\n        _ = u\n    }\n}\n", "fn f(xs option[[]int]) {\n    for x in xs {\n        _ = x\n    }\n}\n"] { let r = hy_check::check_file(&hy_syntax::parse_file("t.hy", src).unwrap()); assert!(r.diagnostics.iter().any(|d| d.code == "HYB-E2009"), "{src}: {:?}", r.diagnostics); } assert!(hy_check::check_file(&hy_syntax::parse_file("t.hy", "fn f(doc serde_json.value) error {\n    for u in doc.array(\"users\")? {\n        _ = u\n    }\n    return nil\n}\n").unwrap()).diagnostics.is_empty()); }
